#!/usr/bin/env python3
from pwn import *

context.log_level = 'debug'  # Enable detailed logging

def test_input(input_str):
    conn = remote('misc.chal.csaw.io', 3001)
    print("Waiting for server prompt...")
    conn.recvuntil(b"Enter your input: ")
    print(f"Sending input: {input_str}")
    conn.sendline(input_str.encode())
    try:
        # Read multiple lines to ensure we get the full response
        response = b""
        while True:
            try:
                line = conn.recvline(timeout=2)
                if not line:
                    break
                response += line
            except:
                break
        return response.decode().strip()
    finally:
        conn.close()

# Test with different coordinates
test_cases = [
    "1 2",
    "3.5 4.2",
    "-1.0 -2.0",
    "0 0",
    "10.5 -7.8"
]

for input_str in test_cases:
    try:
        print(f"\nTesting input: {input_str}")
        result = test_input(input_str)
        print(f"Response: {result}")
        print("-" * 40)
    except Exception as e:
        print(f"Error with input {input_str}: {e}")
        print("-" * 40)

